                NULL AS stu_id,
                staff.id AS staff_id
            FROM libarary_members
            INNER JOIN staff ON libarary_members.member_id = staff.id
            WHERE libarary_members.member_type = 'teacher'
            ORDER BY lib_member_id DESC
        
